@Override // com.facebook.react.bridge.BaseJavaModule
public Map<String, Object> getConstants() {
    HashMap map = new HashMap();
    map.put("PROTOCOL", Constant.PROTOCOL);
    map.put("MODULE_UDP", Constant.MODULE_UDP);
    map.put(Constant.UDP_EVENT, Constant.UDP_EVENT);
    map.put(Constant.UDP_FUNC_START, Constant.UDP_FUNC_START);
    map.put(Constant.UDP_FUNC_STOP, Constant.UDP_FUNC_STOP);
    map.put(Constant.UDP_FUNC_SEND_ACT_PKG, Constant.UDP_FUNC_SEND_ACT_PKG);
    map.put(Constant.UDP_FUNC_SEND_RSP_TO_SERVER, Constant.UDP_FUNC_SEND_RSP_TO_SERVER);
    map.put(Constant.MODULE_LANGUAGE, Constant.MODULE_LANGUAGE);
    map.put("LANGUAGE_SWITCH", Constant.LANGUAGE_SWITCH);
    map.put("MODULE_UI", "UI");
    map.put(Constant.UI_FUNC_SET_STATUSBAR_COLOR, Constant.UI_FUNC_SET_STATUSBAR_COLOR);
    map.put(Constant.MODULE_MEDIA, Constant.MODULE_MEDIA);
    map.put(Constant.MEDIA_EVENT, Constant.MEDIA_EVENT);
    map.put(Constant.MEDIA_FUNC_CONVERT, Constant.MEDIA_FUNC_CONVERT);
    map.put(Constant.MEDIA_FUNC_UPLOAD, Constant.MEDIA_FUNC_UPLOAD);
    map.put(Constant.MEDIA_FUNC_UPLOAD_V2, Constant.MEDIA_FUNC_UPLOAD_V2);
    map.put(Constant.MODULE_HTTP, Constant.MODULE_HTTP);
    map.put(Constant.MODULE_HTTP_SCAN_LOCAL_NET, Constant.MODULE_HTTP_SCAN_LOCAL_NET);
    map.put("MODULE_WS", Constant.MODULE_WS);
    map.put(Constant.WS_FUNC_CONNECT, Constant.WS_FUNC_CONNECT);
    map.put(Constant.WS_FUNC_DISCONNECT, Constant.WS_FUNC_DISCONNECT);
    map.put(Constant.AUD_RECORD_EVENT, Constant.AUD_RECORD_EVENT);
    map.put(Constant.MODULE_AUDIO_RECORD, Constant.MODULE_AUDIO_RECORD);
    map.put(Constant.MODULE_AUDIO_RECORD_START, Constant.MODULE_AUDIO_RECORD_START);
    map.put(Constant.MODULE_AUDIO_RECORD_STOP, Constant.MODULE_AUDIO_RECORD_STOP);
    map.put(Constant.MODULE_AUDIO_RECORD_STATUS, Constant.MODULE_AUDIO_RECORD_STATUS);
    return map;
}
